"""
ImportRun, in place of the 1C_IMPORT_* flags of django-flags and the cache lock of the import. The latest successful
import is copied from Celery's results, so that the admin shows its date and its freshness counts from the start.
"""
import json
import re
from datetime import datetime

import django.utils.timezone
from django.db import migrations, models
from django.utils import timezone


def copy_last_import(apps, schema_editor):
    TaskResult = apps.get_model('django_celery_results', 'TaskResult')
    ImportRun = apps.get_model('shop', 'ImportRun')
    task = TaskResult.objects.filter(task_name='shop.tasks.import1c', status='SUCCESS').exclude(result='null') \
        .order_by('-date_done').first()
    if task is None:
        return
    try:
        file_date = timezone.make_aware(datetime.strptime(json.loads(task.result), '%d.%m.%Y %H:%M:%S'))
    except (TypeError, ValueError):
        file_date = None
    try:
        args = json.loads(task.task_args or '""')  # the JSON of the arguments' repr, such as "('file.csv',)"
    except ValueError:
        args = task.task_args or ''
    file = re.search(r"'([^']+)'", args if isinstance(args, str) else '')
    ImportRun.objects.create(file=file.group(1) if file else '', file_date=file_date, stage='done',
                             started_at=task.date_created or task.date_done, finished_at=task.date_done)


